solution.code:
#include <stdio.h>

int main() {
    int base = 3, exponent = 4;
    int result = 1;
    for (int i = 0; i < exponent; i++) {
        result *= base;
    }
    printf("%d^%d = %d\n", base, exponent, result);
    return 0;
}
